import itertools
import json
from math import comb

# Monomials are represented by exponents of (x, sin(theta), cos(theta)).
def add(a, b):
    result = dict(a)
    for powers, coefficient in b.items():
        result[powers] = result.get(powers, 0) + coefficient
        if result[powers] == 0:
            del result[powers]
    return result

def multiply(a, b):
    result = {}
    for p, u in a.items():
        for q, v in b.items():
            powers = tuple(i + j for i, j in zip(p, q))
            result[powers] = result.get(powers, 0) + u * v
    return {p: v for p, v in result.items() if v}

def negate(a):
    return {p: -v for p, v in a.items()}

def format_polynomial(poly):
    names = ("x", "sin(theta)", "cos(theta)")
    terms = []
    for powers, coefficient in sorted(poly.items(), reverse=True):
        factors = [
            name if exponent == 1 else f"{name}^{exponent}"
            for name, exponent in zip(names, powers) if exponent
        ]
        magnitude = abs(coefficient)
        body = "*".join(
            ([str(magnitude)] if magnitude != 1 or not factors else [])
            + factors
        )
        if not terms:
            terms.append(("-" if coefficient < 0 else "") + body)
        else:
            terms.append((" - " if coefficient < 0 else " + ") + body)
    return "".join(terms) or "0"

one = {(0, 0, 0): 1}
x = {(1, 0, 0): 1}
s = {(0, 1, 0): 1}
c = {(0, 0, 1): 1}

matrix = [
    [x, s, c],
    [negate(s), negate(x), one],
    [c, one, x],
]

determinant = {}
for permutation in itertools.permutations(range(3)):
    inversions = sum(
        permutation[i] > permutation[j]
        for i in range(3) for j in range(i + 1, 3)
    )
    term = one
    for row, column in enumerate(permutation):
        term = multiply(term, matrix[row][column])
    determinant = add(determinant, negate(term) if inversions % 2 else term)

# Substitute cos(theta)^2 = 1 - sin(theta)^2 exactly.
reduced = {}
for (px, ps, pc), coefficient in determinant.items():
    quotient, remainder = divmod(pc, 2)
    for k in range(quotient + 1):
        powers = (px, ps + 2 * k, remainder)
        value = coefficient * comb(quotient, k) * (-1) ** k
        reduced = add(reduced, {powers: value})

print(json.dumps({
    "final_answer": format_polynomial(reduced),
    "evidence": {
        "determinant_expansion": format_polynomial(determinant),
        "identity": "sin(theta)^2 + cos(theta)^2 = 1",
        "method": "Exact six-permutation determinant expansion and polynomial reduction"
    }
}, separators=(",", ":")))
